import { customElement } from '@umbraco-cms/backoffice/external/lit';
import {
    UmbPropertyValueChangeEvent,
    type UmbPropertyEditorConfigCollection,
    type UmbPropertyEditorUiElement,
} from '@umbraco-cms/backoffice/property-editor';
import { createElement } from 'react';
import { createRoot, type Root } from 'react-dom/client';
import { SerpEditorApp, type SerpValue } from './serp-editor-app';

const elementName = 'n3o-serp-editor';

// Web-component SHELL for the SERP property editor. Umbraco's backoffice only loads custom
// elements, so this thin element owns the Umbraco contract (value/config + UmbPropertyValueChangeEvent)
// and mounts the React UI (SerpEditorApp) into its shadow root. React itself is NOT bundled here —
// it is external and resolved at runtime from the shared N3O.Umbraco.React import map.
//
// This is the reference bridge pattern for the React migration — mirror it for every property editor.
@customElement(elementName)
export class N3oSerpEditorElement extends HTMLElement implements UmbPropertyEditorUiElement {
    #root?: Root;
    #mount: HTMLDivElement;
    #value: SerpValue = { title: '', description: '' };
    #maxCharsTitle = 60;
    #maxCharsDescription = 160;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        this.#mount = document.createElement('div');
        shadow.appendChild(this.#mount);
    }

    get value(): SerpValue {
        return this.#value;
    }

    set value(value: SerpValue | undefined) {
        this.#value = value ?? { title: '', description: '' };
        this.#render();
    }

    // Config (prevalues) arrives as UmbPropertyEditorConfigCollection.
    public set config(config: UmbPropertyEditorConfigCollection | undefined) {
        const maxCharsTitle = Number.parseInt(config?.getValueByAlias('maxCharsTitle') ?? '', 10);
        const maxCharsDescription = Number.parseInt(config?.getValueByAlias('maxCharsDescription') ?? '', 10);

        if (!Number.isNaN(maxCharsTitle) && maxCharsTitle > 0) {
            this.#maxCharsTitle = maxCharsTitle;
        }

        if (!Number.isNaN(maxCharsDescription) && maxCharsDescription > 0) {
            this.#maxCharsDescription = maxCharsDescription;
        }

        this.#render();
    }

    connectedCallback(): void {
        this.#root ??= createRoot(this.#mount);
        this.#render();
    }

    disconnectedCallback(): void {
        this.#root?.unmount();
        this.#root = undefined;
    }

    #render(): void {
        this.#root?.render(
            createElement(SerpEditorApp, {
                value: this.#value,
                maxCharsTitle: this.#maxCharsTitle,
                maxCharsDescription: this.#maxCharsDescription,
                onChange: (value: SerpValue) => {
                    this.#value = value;
                    this.dispatchEvent(new UmbPropertyValueChangeEvent());
                },
            }),
        );
    }
}

export default N3oSerpEditorElement;

declare global {
    interface HTMLElementTagNameMap {
        [elementName]: N3oSerpEditorElement;
    }
}
